@php $priorities = $studyRecommendations->flatMap(fn ($plan) => collect($plan['recommendations'])->map(fn ($r) => [...$r,'course'=>$plan['course']]))->filter(fn ($r) => in_array($r['topic']->mastery?->status ?? 'no_evidence',['fragile','developing','no_evidence','insufficient_evidence']))->sortByDesc('priority')->take(6); @endphp
@forelse($priorities as $r)<div class="learning-line"><strong>{{ $r['topic']->title }}</strong><p>{{ $r['course']->name }} · {{ $r['reason'] }}</p><div class="learning-actions"><a href="{{ route('study.create',['course_id'=>$r['course']->id,'topic_id'=>$r['topic']->id,'now'=>1],false) }}">Estudar →</a><a href="{{ route('practice.runs.create',['course_id'=>$r['course']->id,'topic_id'=>$r['topic']->id],false) }}">Treinar →</a></div></div>@empty<p class="empty">Sem prioridades identificadas. Assinala a matéria lecionada na UC e realiza um treino para avaliar o domínio.</p>@endforelse</section>
